param(
    [string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot),
    [string]$ProductionOutputPath = (Join-Path ([IO.Path]::GetTempPath()) 'halcon-vm-s42-production-run.png'),
    [string]$ProjectiveOutputPath = (Join-Path ([IO.Path]::GetTempPath()) 'halcon-vm-s42-xld-projective.png')
)
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework;Add-Type -AssemblyName System.Drawing
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function WaitTask($task){$watch=[Diagnostics.Stopwatch]::StartNew();while((-not$task.IsCompleted)-and($watch.ElapsedMilliseconds-lt30000)){Pump 20};if(-not$task.IsCompleted){throw 'Task timeout'};if($task.IsFaulted){throw $task.Exception.Flatten().InnerExceptions[0]};$task.GetAwaiter().GetResult()|Out-Null}
function Shot([string]$path){$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$w=[Math]::Max(1,[int][Math]::Ceiling($b.X-$a.X));$h=[Math]::Max(1,[int][Math]::Ceiling($b.Y-$a.Y));$bitmap=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($w,$h));$bitmap.Save($path,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bitmap.Dispose()};"${w}x${h}"}
function ImageFile([string]$path){$bitmap=[Drawing.Bitmap]::new(960,620);$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.Clear([Drawing.Color]::FromArgb(19,29,46));$green=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(80,210,145));$orange=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(245,160,55));try{$g.FillRectangle($green,125,110,360,245);$g.FillEllipse($orange,570,175,225,225)}finally{$green.Dispose();$orange.Dispose()};$bitmap.Save($path,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bitmap.Dispose()}}
function SourceXld(){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]@([double]100,100,330,330,100),[HalconDotNet.HTuple]@([double]150,520,520,150,150));$x}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s42-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null;$image=Join-Path $temp 'production_part.png';ImageFile $image
foreach($path in @($ProductionOutputPath,$ProjectiveOutputPath)){$parent=[IO.Path]::GetDirectoryName($path);if(-not[string]::IsNullOrWhiteSpace($parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null}}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$args=New-Object 'object[]' 1;$args[0]=$temp.ToString();$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke($args);$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke($args);$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$main.GetField($name,$all).GetValue($window)}
$flow=$main.GetField('flowTools',$private).GetValue($window);$dispose=$main.GetMethod('DisposeFlowTools',$private);$create=$main.GetMethod('CreateFlowTool',$private);function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
$window.WindowStartupLocation=[Windows.WindowStartupLocation]::Manual;$window.Left=2;$window.Top=2;$window.Width=1900;$window.Height=1060;$window.Topmost=$true;$window.Show();$window.Activate()|Out-Null;Pump 500

$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$threshold=Tool ImageThreshold 'Production Full Domain';$threshold.Parameters.ImageThresholdMinGray=0;$threshold.Parameters.ImageThresholdMaxGray=255;$flow.Add($threshold);$loadQueue=$main.GetMethods($private)|Where-Object{$_.Name-eq'LoadImageQueue'-and$_.GetParameters().Count-eq1}|Select-Object -First 1;$arg=New-Object 'object[]' 1;$arg[0]=[string[]]@($image);$loadQueue.Invoke($window,$arg)|Out-Null;(F 'RecipeNameEditTextBox').Text='S42 Production Recipe';(F 'FlowTimeoutTextBox').Text='0';$modeType=$assembly.GetType('HalconWinFormsDemo.Models.VmFlowRunRequestMode',$true);WaitTask($main.GetMethod('RunInspectionRangeAsync',$private).Invoke($window,[object[]]@([Enum]::Parse($modeType,'Full'),'S42 UI production')));$main.GetMethod('AppendAlarm',$private).Invoke($window,[object[]]@('Demo alarm from the shared real alarm stream'))|Out-Null;$main.GetMethod('SetProductionRunMode',$private).Invoke($window,[object[]]@($true))|Out-Null;Pump 900;$productionSize=Shot $ProductionOutputPath

$main.GetMethod('SetProductionRunMode',$private).Invoke($window,[object[]]@($false))|Out-Null;$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$producer=Tool SubpixelEdgeExtraction 'Source XLD';$projective=Tool XldProjectiveTransform 'Projective Compensation';$fit=Tool XldLineFitting 'Transformed Line Fit';$projective.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$projective.ToolId,'XLD');$projective.Parameters.XldProjectiveTargetRow1=125;$projective.Parameters.XldProjectiveTargetColumn1=185;$projective.Parameters.XldProjectiveTargetRow2=80;$projective.Parameters.XldProjectiveTargetColumn2=610;$projective.Parameters.XldProjectiveTargetRow3=370;$projective.Parameters.XldProjectiveTargetColumn3=560;$projective.Parameters.XldProjectiveTargetRow4=350;$projective.Parameters.XldProjectiveTargetColumn4=110;foreach($tool in @($producer,$projective,$fit)){$flow.Add($tool)}
$xld=SourceXld;try{$snapshot=$snapshotType.GetMethod('Create',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@($xld,$producer.ToolId,$producer.InstanceName,'XLD'));$producer.SetOutputValue('XLD',$snapshot);$producer.SetOutputValue('ContourCount',[double]1);$producer.ResultCode='OK'}finally{$xld.Dispose()};$execute=$main.GetMethod('ExecuteFlowTool',$private);foreach($tool in @($projective,$fit)){$execute.Invoke($window,[object[]]@($tool,'S42 UI projective'))|Out-Null};(F 'FlowToolList').SelectedItem=$projective;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($projective))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedIndex=0;(F 'ImageQueuePanel').Visibility=[Windows.Visibility]::Collapsed;(F 'ImageQueuePanelToggleButton').IsChecked=$false;(F 'ImageWorkspaceRow').Height=[Windows.GridLength]::new(330);(F 'RightConfigurationRow').Height=[Windows.GridLength]::new(410);$main.GetMethod('RefreshResultOverlayLayers',$private).Invoke($window,@())|Out-Null;$main.GetMethod('RefreshFlowSelectionFlags',$private).Invoke($window,@())|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null;Pump 900;$projectiveSize=Shot $ProjectiveOutputPath
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output "S42_UI_CAPTURE=PASS; Production=$ProductionOutputPath; Projective=$ProjectiveOutputPath; ProductionSize=$productionSize; ProjectiveSize=$projectiveSize; A=SHARED_REAL_PRODUCTION_RUN_PAGE; B=HALCON_PROJECTIVE_TRANS_CONTOUR_XLD"
